/**
 * Pre-bundled benchmark samples for 1-click verification in DeepShield.
 */

const SAMPLES = {
  real: {
    name: 'grace_hopper_navy_real.jpg',
    mime: 'image/jpeg',
    base64: '',
  },
  fake: {
    name: 'sample_fake_3.jpg',
    mime: 'image/jpeg',
    base64: '',
  },
  multi: {
    name: 'multi_face_sample.jpg',
    mime: 'image/jpeg',
    base64: '',
  },
  none: {
    name: 'no_face_sample.jpg',
    mime: 'image/jpeg',
    base64: '',
  },
};

export function getSampleFile(type: 'real' | 'fake' | 'multi' | 'none'): File {
  const sample = SAMPLES[type];
  const binaryString = atob(sample.base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new File([bytes], sample.name, { type: sample.mime });
}
